from collections import *
for t in range(int(input())):
	(n, k) = map(int, input().split())
	susjedi = defaultdict(list)
	for i in range(n):
		s = input()
		for j in range(n):
			if abs(i - j) <= k and s[j] == '1' and (i != j):
				susjedi[i].append(j)

	def bfs(x):
		udaljenost = [-1] * n
		udaljenost[x] = 0
		q = deque()
		q.append(x)
		while len(q) > 0:
			x = q.popleft()
			for y in susjedi[x]:
				if udaljenost[y] == -1:
					udaljenost[y] = udaljenost[x] + 1
					q.append(y)
		return udaljenost[n - 1]
	print(bfs(0))
